<template x-if="modal==='profiles'"><div class="form-stack">
    <p class="muted">Profil menggunakan nama tipe ONU, bandwidth, VLAN, dan WAN profile yang tersedia pada OLT. Kelola profil sebelum memasang pelanggan.</p>
    <button class="btn primary" @click="editServiceProfile()" x-show="db.permissions.manage">Tambah profil layanan</button>
    <div class="table-scroll"><table><thead><tr><th>Profil</th><th>Mode</th><th>Tipe ONU</th><th>VLAN</th><th>Aksi</th></tr></thead><tbody><template x-for="profile in serviceProfiles" :key="profile.id"><tr><td x-text="profile.name"></td><td x-text="profile.mode"></td><td x-text="profile.onu_type"></td><td x-text="profile.vlan_id??'—'"></td><td><button class="text-button" @click="editServiceProfile(profile)" x-show="db.permissions.manage">Edit profil</button> <button class="text-button red-text" @click="archiveServiceProfile(profile)" x-show="db.permissions.manage">Arsipkan</button></td></tr></template></tbody></table></div>
    <template x-if="serviceProfileForm"><form class="form-stack inline-editor" @submit.prevent="saveServiceProfile()"><div class="form-grid">
        <label>Nama profil layanan<input x-model="serviceProfileForm.name" required maxlength="100"></label><label>Tipe ONU di OLT<input x-model="serviceProfileForm.onu_type" required maxlength="40" placeholder="F609"></label>
        <label>Mode layanan<select aria-label="Mode layanan" x-model="serviceProfileForm.mode"><option value="registration">Pendaftaran dan nama saja</option><option value="bridge">Bridge</option><option value="pppoe">PPPoE melalui OMCI</option><option value="custom">Template CLI</option></select></label>
        <label x-show="['bridge','pppoe'].includes(serviceProfileForm.mode)">Profil upstream<input x-model="serviceProfileForm.upstream_profile" placeholder="Nama profil TCONT di OLT"></label><label x-show="['bridge','pppoe'].includes(serviceProfileForm.mode)">Profil downstream<input x-model="serviceProfileForm.downstream_profile" placeholder="Nama profil downstream di OLT"></label><label x-show="['bridge','pppoe'].includes(serviceProfileForm.mode)">VLAN layanan<input type="number" x-model.number="serviceProfileForm.vlan_id" min="1" max="4094"></label><label x-show="serviceProfileForm.mode==='pppoe'">WAN VLAN profile<input x-model="serviceProfileForm.wan_profile" placeholder="Nama VLAN profile OMCI di OLT"></label>
    </div><label x-show="serviceProfileForm.mode==='custom'">Perintah setelah nama ONU<textarea x-model="serviceProfileForm.commandsText" rows="7" placeholder="Satu perintah per baris"></textarea><small class="muted">Placeholder: &#123;&#123;interface&#125;&#125;, &#123;&#123;port&#125;&#125;, &#123;&#123;onu_index&#125;&#125;, &#123;&#123;sn&#125;&#125;, &#123;&#123;name&#125;&#125;, &#123;&#123;pppoe_user&#125;&#125;, &#123;&#123;pppoe_password&#125;&#125;. Mulai dari konteks interface ONU. Rahasia diisi saat pemasangan.</small></label><div class="form-grid" x-show="serviceProfileForm.mode==='custom'"><label>Baris hasil pada interface ONU<textarea x-model="serviceProfileForm.interfaceVerificationText" rows="4" placeholder="tcont 1 profile UP-1M"></textarea></label><label>Baris hasil pada pengelolaan ONU<textarea x-model="serviceProfileForm.managementVerificationText" rows="4" placeholder="service internet gemport 1 vlan 123"></textarea></label></div><p class="muted small" x-show="serviceProfileForm.mode==='custom'">Isi hasil konfigurasi yang harus terbaca kembali, satu baris per entri. Gunakan placeholder untuk rahasia. Minimal satu baris verifikasi wajib diisi.</p><div class="modal-actions"><button type="button" class="btn secondary" @click="serviceProfileForm=null">Batal</button><button class="btn primary" :disabled="busy">Simpan profil layanan</button></div></form></template>
</div></template>
<template x-if="modal==='provision' && selected"><div class="form-stack">
    <div class="module-toolbar"><button class="btn secondary" @click="discoverOnus()" :disabled="discoveryLoading" x-text="discoveryLoading?'Memindai OLT...':'Pindai ONU baru'"></button><button class="text-button" @click="open('profiles')">Kelola profil layanan</button></div>
    @include('partials.skeleton',['show'=>'discoveryLoading&&!discovery.onus.length'])
    <p class="muted" x-show="selected.connection_mode==='simulator'">Mode simulator: masukkan SN dan posisi untuk mencoba alur pemasangan lokal.</p>

    <p class="muted" x-show="selected.connection_mode==='real'&&!discoveryLoading&&!discovery.onus.length">Belum ada ONU baru yang terdeteksi. Klik Pindai ONU baru.</p>
    <form class="form-stack" @submit.prevent="previewProvision()" @input="provisionPlan=null" @change="provisionPlan=null"><fieldset :disabled="busy" class="form-stack min-w-0 border-0 p-0">
        <label x-show="discovery.onus.length">ONU terdeteksi<select @change="selectDetected($event.target.value)"><option value="">Pilih ONU baru</option><template x-for="(onu,index) in discovery.onus" :key="index"><option :value="index" x-text="onu.sn+' / '+onu.frame+'/'+onu.slot+'/'+onu.port"></option></template></select></label>
        <div class="form-grid"><label>Profil pemasangan<select aria-label="Profil pemasangan" x-model="provisionForm.profile_id" required><option value="">Pilih profil layanan</option><template x-for="profile in serviceProfiles" :key="profile.id"><option :value="profile.id" x-text="profile.name+' / '+profile.mode"></option></template></select></label><label>Nama pelanggan di OLT<input aria-label="Nama pelanggan di OLT" x-model="provisionForm.name" required maxlength="80" placeholder="PELANGGAN-BARU"><small class="muted">Gunakan huruf, angka, titik, tanda kurung, garis bawah atau tanda hubung.</small></label><label>Serial ONU<input x-model="provisionForm.sn" required pattern="[A-Za-z]{4}[A-Fa-f0-9]{8}"></label><label>Frame<input type="number" x-model.number="provisionForm.frame" min="1" max="255" required></label><label>Slot<input type="number" x-model.number="provisionForm.slot" min="1" max="255" required></label><label>Port PON<input type="number" x-model.number="provisionForm.port" min="1" max="32" required></label><label>ID ONU tujuan<input type="number" x-model.number="provisionForm.onu_index" min="1" max="256" required></label></div>
        <div class="form-grid" x-show="needsPppoe()"><label>Username PPPoE<input x-model="provisionForm.pppoe_user" autocomplete="off" maxlength="100"></label><label>Password PPPoE<input type="password" x-model="provisionForm.pppoe_password" autocomplete="new-password" maxlength="100"></label></div>
        <div class="modal-actions"><button class="btn primary" :disabled="busy||!serviceProfiles.length">Periksa dan pratinjau</button></div>
    </fieldset></form>
    <template x-if="provisionPlan"><section class="inline-editor"><h3>Konfirmasi pemasangan ONU</h3><p><strong x-text="provisionPlan.plan.parameters.name"></strong> &middot; <span x-text="provisionPlan.plan.parameters.sn"></span></p><p class="muted">Rencana berlaku 10 menit dan hanya dapat dikirim sekali. Posisi serta ketersediaan ID diperiksa kembali pada perangkat sebelum pendaftaran.</p><pre class="terminal-output" x-text="provisionPlan.commands.join('\n')"></pre><div class="modal-actions"><button class="btn secondary" @click="provisionPlan=null">Batal</button><button class="btn primary" @click="applyProvision()" :disabled="busy">Konfirmasi pasang ONU</button></div></section></template>
</div></template>
